// Expect JSON payload like {"temp1":42.5,"humidity":38}
// or a bare number for a single temperature key.
let payload = msg.payload;
if (typeof payload === "string") {
  try { payload = JSON.parse(payload); } catch (e) { return null; }
}
if (typeof payload === "number") {
  payload = { temp1: payload };
}
if (!payload || typeof payload !== "object") {
  node.warn("ThermalTrace bridge: payload must be JSON object");
  return null;
}
msg.headers = {
  "Content-Type": "application/json",
  "X-Ingest-Key": env.get("THERMALTRACE_INGEST_KEY") || "YOUR_DEVICE_KEY"
};
msg.payload = {
  topic: msg.topic || "home/garage/temp",
  message: payload
};
return msg;
